package io.forgeloop.control.api;
import io.forgeloop.control.application.LeaseGrant; import io.forgeloop.control.application.TaskLeaseService; import io.forgeloop.control.domain.TaskLease; import org.springframework.graphql.data.method.annotation.*; import org.springframework.stereotype.Controller;
/** Runner-facing mutations are deliberately separated from operator control-plane mutations. */
@Controller public class RunnerExecutionController { private final TaskLeaseService leases; public RunnerExecutionController(TaskLeaseService leases){this.leases=leases;} @MutationMapping public LeaseGrant claimTaskLease(@Argument String taskId,@Argument String runnerId){return leases.claim(taskId,runnerId);}@MutationMapping public TaskLease acknowledgeTaskLease(@Argument String leaseId,@Argument String runnerId,@Argument String nonce){return leases.acknowledge(leaseId,runnerId,nonce);} }
